        EntityCell targetEntityCell = (EntityCell) targetCell;

        // Can't move into StopCell
        if (targetEntityCell instanceof StopCell) {
            return new MoveResult.Invalid(newPosition);
        }

        Entity targetEntity = targetEntityCell.getEntity();

        // If mine, player dies
        if (targetEntity instanceof Mine) {
            return new MoveResult.Valid.Dead(newPosition, newPosition);
        }

