package pa1.controller;

import pa1.model.*;

import java.util.*;

/**
 * Controller for {@link GameBoard}.
 *
 * <p>
 * This class is responsible for providing high-level operations to mutate a {@link GameBoard}. This should be the only
 * class which mutates the game board; Other classes should use this class to mutate the game board.
 * </p>
 */
public class GameBoardController {

    private final GameBoard gameBoard;

    /**
     * Creates an instance.
     *
     * @param gameBoard The instance of {@link GameBoard} to control.
     */
    public GameBoardController(final GameBoard gameBoard) {
        this.gameBoard = gameBoard;
    }

    /**
     * Moves the player in the given direction.
     *
     * <p>
     * You should ensure that the game board is only mutated if the move is valid and results in the player still being
     * alive. If the player dies after moving or the move is invalid, the game board should remain in the same state as
     * before this method was called.
     * </p>
     *
     * @param direction Direction to move the player in.
     * @return An instance of {@link MoveResult} representing the result of this action.
     */
    public MoveResult makeMove(final Direction direction) {
        Player player = gameBoard.getPlayer();
        EntityCell currCell = player.getOwner();
        Position currPos = currCell.getPosition();

        // Calculate new position
        PositionOffset offset = direction.getOffset();
        Position newPos = currPos.offsetByOrNull(offset, gameBoard.getNumRows(), gameBoard.getNumCols());
        if (newPos == null) {
            // Out of bounds
            return new MoveResult.Invalid(currPos);
        }

        Cell destCell = gameBoard.getCell(newPos);
        if (!(destCell instanceof EntityCell)) {
            // Not a valid cell to move into
            return new MoveResult.Invalid(currPos);
        }

        EntityCell destEntityCell = (EntityCell) destCell;
        Entity destEntity = destEntityCell.getEntity();

        // Check for StopCell or blocked cell
        if (destCell instanceof StopCell) {
            return new MoveResult.Invalid(currPos);
        }

        // Prepare to collect gems and extra lives
        List<Position> collectedGems = new ArrayList<>();
        List<Position> collectedExtraLives = new ArrayList<>();

        // Check for Mine
        if (destEntity instanceof Mine) {
            // Player dies, but move is valid
            // Do not mutate the board
            return new MoveResult.Valid.Dead(newPos, newPos);
        }

        // Check for Gem or ExtraLife
        if (destEntity instanceof Gem) {
            collectedGems.add(newPos);
        } else if (destEntity instanceof ExtraLife) {
            collectedExtraLives.add(newPos);
        }

        // Move is valid and player is alive, mutate the board
        // Remove player from current cell
        currCell.setEntity(null);
        // Remove collected entity from destination cell
        destEntityCell.setEntity(null);
        // Place player in destination cell
        destEntityCell.setEntity(player);

        return new MoveResult.Valid.Alive(newPos, currPos, collectedGems, collectedExtraLives);
    }

    /**
     * Undoes a move by reverting all changes performed by the specified move.
     *
     * <p>
     * Hint: Undoing a move is effectively the same as reversing everything you have done to make a move.
     * </p>
     *
     * @param prevMove The {@link MoveResult} object to revert.
     */
    public void undoMove(final MoveResult prevMove) {
        if (prevMove instanceof MoveResult.Valid.Alive) {
            MoveResult.Valid.Alive aliveMove = (MoveResult.Valid.Alive) prevMove;
            Position from = aliveMove.origPosition;
            Position to = aliveMove.newPosition;
            Player player = gameBoard.getPlayer();

            // Remove player from current cell
            EntityCell toCell = gameBoard.getEntityCell(to);
            toCell.setEntity(null);

            // Restore collected gems
            for (Position gemPos : aliveMove.collectedGems) {
                EntityCell cell = gameBoard.getEntityCell(gemPos);
                cell.setEntity(new Gem(cell));
            }

            // Restore collected extra lives
            for (Position lifePos : aliveMove.collectedExtraLives) {
                EntityCell cell = gameBoard.getEntityCell(lifePos);
                cell.setEntity(new ExtraLife(cell));
            }

            // Place player back to original cell
            EntityCell fromCell = gameBoard.getEntityCell(from);
            fromCell.setEntity(player);

        } else if (prevMove instanceof MoveResult.Valid.Dead) {
            // No board mutation was made, so nothing to undo
        } else if (prevMove instanceof MoveResult.Invalid) {
            // No board mutation was made, so nothing to undo
        }
    }
}
```

**Notes:**
- The controller only mutates the board if the move is valid and the player survives.
- If the player moves onto a `Gem` or `ExtraLife`, those are removed from the board and tracked in the move result.
- If the player moves onto a `Mine`, the move is valid but the board is not mutated (the player "dies" but is not moved).
- If the move is invalid (out of bounds, into a `StopCell`, etc.), the board is not mutated.
- `undoMove` restores the player and any collected entities to their previous positions.

This implementation assumes the `setEntity` and `getEntity` methods work as expected, and that `EntityCell` and `Player` are implemented according to your provided stubs.

