```java
package pa1.model;

import java.util.*;

/**
 * The main game board of the game.
 *
 * <p>
 * The top-left hand corner of the game board is the "origin" of the board (0, 0).
 * </p>
 */
public class GameBoard {

    /**
     * Number of rows in the game board.
     */
    private final int numRows;
    /**
     * Number of columns in the game board.
     */
    private final int numCols;

    /**
     * 2D array representing each cell in the game board.
     */
    private final Cell[][] board;

    /**
     * The instance of {@link Player} on this game board.
     */
    private final Player player;

    /**
     * Creates an instance using the provided creation parameters.
     *
     * @param numRows The number of rows in the game board.
     * @param numCols The number of columns in the game board.
     * @param cells   The initial values of cells.
     * @throws IllegalArgumentException if any of the following are true:
     *                                  <ul>
     *                                      <li>{@code numRows} is not equal to {@code cells.length}</li>
     *                                      <li>{@code numCols} is not equal to {@code cells[0].length}</li>
     *                                      <li>There is no player or more than one player in {@code cells}</li>
     *                                      <li>There are no gems in {@code cells}</li>
     *                                      <li>There are some gems which cannot be reached by the player</li>
     *                                  </ul>
     */
    public GameBoard(final int numRows, final int numCols, final Cell[][] cells) {
        // Check dimensions
        if (cells == null || cells.length != numRows)
            throw new IllegalArgumentException("numRows does not match cells.length");
        for (int i = 0; i < numRows; i++) {
            if (cells[i] == null || cells[i].length != numCols)
                throw new IllegalArgumentException("numCols does not match cells[0].length");
        }

        this.numRows = numRows;
        this.numCols = numCols;
        this.board = new Cell[numRows][numCols];

        Player foundPlayer = null;
        List<Position> gemPositions = new ArrayList<>();
        Position playerPosition = null;

        // Copy cells and find player/gems
        for (int r = 0; r < numRows; r++) {
            for (int c = 0; c < numCols; c++) {
                Cell cell = cells[r][c];
                if (cell == null)
                    throw new IllegalArgumentException("Cell at (" + r + "," + c + ") is null");
                board[r][c] = cell;
                if (cell instanceof EntityCell) {
                    Entity entity = ((EntityCell) cell).getEntity();
                    if (entity instanceof Player) {
                        if (foundPlayer != null)
                            throw new IllegalArgumentException("More than one player found");
                        foundPlayer = (Player) entity;
                        playerPosition = cell.getPosition();
                    } else if (entity instanceof Gem) {
                        gemPositions.add(cell.getPosition());
                    }
                }
            }
        }

        if (foundPlayer == null)
            throw new IllegalArgumentException("No player found in cells");
        if (gemPositions.isEmpty())
            throw new IllegalArgumentException("No gems found in cells");

        // Check reachability of all gems from player
        if (!allGemsReachable(playerPosition, gemPositions)) {
            throw new IllegalArgumentException("Some gems are not reachable by the player");
        }

        this.player = foundPlayer;
    }

    /**
     * Returns the {@link Cell}s of a single row of the game board.
     *
     * @param row Row index.
     * @return 1D array representing the row. The first element in the array corresponds to the leftmost element of the
     * row.
     */
    public Cell[] getRow(final int row) {
        if (row < 0 || row >= numRows)
            throw new IndexOutOfBoundsException("Row out of bounds: " + row);
        return Arrays.copyOf(board[row], numCols);
    }

    /**
     * Returns the {@link Cell}s of a single column of the game board.
     *
     * @param col Column index.
     * @return 1D array representing the column. The first element in the array corresponds to the topmost element of
     * the row.
     */
    public Cell[] getCol(final int col) {
        if (col < 0 || col >= numCols)
            throw new IndexOutOfBoundsException("Column out of bounds: " + col);
        Cell[] column = new Cell[numRows];
        for (int r = 0; r < numRows; r++) {
            column[r] = board[r][col];
        }
        return column;
    }

    /**
     * Returns a single cell of the game board.
     *
     * @param row Row index.
     * @param col Column index.
     * @return The {@link Cell} instance at the specified location.
     */
    public Cell getCell(final int row, final int col) {
        if (row < 0 || row >= numRows || col < 0 || col >= numCols)
            throw new IndexOutOfBoundsException("Cell position out of bounds: (" + row + "," + col + ")");
        return board[row][col];
    }

    /**
     * Returns a single cell of the game board.
     *
     * @param position The position object representing the location of the cell.
     * @return The {@link Cell} instance at the specified location.
     */
    public Cell getCell(final Position position) {
        return getCell(position.row(), position.col());
    }

    /**
     * Returns an {@link EntityCell} on the game board.
     *
     * <p>
     * This method is a convenience method for getting a cell which is unconditionally known to be an entity cell.
     * </p>
     *
     * @param row Row index.
     * @param col Column index.
     * @return The {@link EntityCell} instance at the specified location.
     * @throws IllegalArgumentException if the cell at the specified position is not an instance of {@link EntityCell}.
     */
    public EntityCell getEntityCell(final int row, final int col) {
        Cell cell = getCell(row, col);
        if (!(cell instanceof EntityCell))
            throw new IllegalArgumentException("Cell at (" + row + "," + col + ") is not an EntityCell");
        return (EntityCell) cell;
    }

    /**
     * Returns an {@link EntityCell} on the game board.
     *
     * <p>
     * This method is a convenience method for getting a cell which is unconditionally known to be an entity cell.
     * </p>
     *
     * @param position The position object representing the location of the cell.
     * @return The {@link EntityCell} instance at the specified location.
     * @throws IllegalArgumentException if the cell at the specified position is not an instance of {@link EntityCell}.
     */
    public EntityCell getEntityCell(final Position position) {
        return getEntityCell(position.row(), position.col());
    }

    /**
     * @return The number of rows of this game board.
     */
    public int getNumRows() {
        return numRows;
    }

    /**
     * @return The number of columns of this game board.
     */
    public int getNumCols() {
        return numCols;
    }

    /**
     * @return The player instance.
     */
    public Player getPlayer() {
        return player;
    }

    /**
     * @return The number of gems still present in the game board.
     */
    public int getNumGems() {
        int count = 0;
        for (int r = 0; r < numRows; r++) {
            for (int c = 0; c < numCols; c++) {
                Cell cell = board[r][c];
                if (cell instanceof EntityCell) {
                    Entity entity = ((EntityCell) cell).getEntity();
                    if (entity instanceof Gem) {
                        count++;
                    }
                }
            }
        }
        return count;
    }

    /**
     * Helper method to check if all gems are reachable from the player's position.
     */
    private boolean allGemsReachable(Position playerPos, List<Position> gemPositions) {
        Set<Position> visited = new HashSet<>();
        Queue<Position> queue = new LinkedList<>();
        queue.add(playerPos);
        visited.add(playerPos);

        Set<Position> gemsToFind = new HashSet<>(gemPositions);

        int[] dRows = {-1, 1, 0, 0};
        int[] dCols = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            Position pos = queue.poll();
            if (gemsToFind.contains(pos)) {
                gemsToFind.remove(pos);
                if (gemsToFind.isEmpty())
                    return true;
            }
            for (int i = 0; i < 4; i++) {
                int newRow = pos.row() + dRows[i];
                int newCol = pos.col() + dCols[i];
                if (newRow >= 0 && newRow < numRows && newCol >= 0 && newCol < numCols) {
                    Position newPos = new Position(newRow, newCol);
                    if (!visited.contains(newPos)) {
                        Cell cell = board[newRow][newCol];
                        // Player can only walk on EntityCell or StopCell, not Wall
                        if (cell instanceof EntityCell || cell instanceof StopCell) {
                            visited.add(newPos);
                            queue.add(newPos);
                        }
                    }
                }
            }
        }
        return gemsToFind.isEmpty();
    }
}
```

**Notes:**
- The constructor checks all the requirements and throws exceptions as specified.
- The reachability check uses BFS and only traverses through `EntityCell` and `StopCell` (not `Wall`).
- All getters and utility methods are implemented.
- Defensive copies are made where appropriate (e.g., `getRow`, `getCol`).
- Index checks are performed for all accessors.

