     * @return The number of gems still present in the game board.
     */
    public int getNumGems() {
        int count = 0;
        for (int r = 0; r < numRows; r++) {
            for (int c = 0; c < numCols; c++) {
                Cell cell = board[r][c];
                if (cell instanceof EntityCell) {
                    Entity entity = ((EntityCell) cell).getEntity();
                    if (entity instanceof Gem) {
                        count++;
                    }
                }
            }
        }
        return count;
    }

    /**
     * Helper method to check if all gems are reachable from the player's position.
     */
    private boolean allGemsReachable(Position playerPos, List<Position> gemPositions) {
        Set<Position> visited = new HashSet<>();
        Queue<Position> queue = new LinkedList<>();
        queue.add(playerPos);
        visited.add(playerPos);

        Set<Position> gemsToFind = new HashSet<>(gemPositions);

        while (!queue.isEmpty() && !gemsToFind.isEmpty()) {
            Position pos = queue.poll();
            if (gemsToFind.contains(pos)) {
                gemsToFind.remove(pos);
            }
            for (Direction dir : Direction.values()) {
                PositionOffset offset = dir.getOffset();
                int newRow = pos.row() + offset.dRow();
                int newCol = pos.col() + offset.dCol();
                if (newRow >= 0 && newRow < numRows && newCol >= 0 && newCol < numCols) {
                    Cell neighbor = board[newRow][newCol];
                    if (!(neighbor instanceof Wall)) {
                        Position neighborPos = new Position(newRow, newCol);
                        if (!visited.contains(neighborPos)) {
                            visited.add(neighborPos);
                            queue.add(neighborPos);
                        }
                    }
                }
            }
        }
        return gemsToFind.isEmpty();
    }
